// MIT License. Seller-origin + payment-quote proof for x402 v2 Bazaar.
// This is NOT Stellar wallet ownership, payment verification or settlement.
import {createHash, createPrivateKey, createPublicKey, randomBytes, sign, verify} from 'node:crypto';
import {lookup} from 'node:dns/promises';
import {BlockList, isIP} from 'node:net';
import https from 'node:https';

export const PROOF_DOMAIN = 'stellar-bazaar-seller-origin-quote-proof/v2';
export const WELL_KNOWN = '/.well-known/x402-bazaar-proof';
const METHODS = new Set(['GET', 'HEAD', 'DELETE', 'POST', 'PUT', 'PATCH']);
const MAX_LIFETIME_MS = 120_000;
const CLOCK_SKEW_MS = 5_000;
const CHALLENGE_RE = /^[A-Za-z0-9_-]{43}$/; // 32 random bytes base64url
const ACCEPTS_RE = /^\d+$/; // x402 atomic amount string; no floating point conversions
const plain = v => v !== null && typeof v === 'object' && !Array.isArray(v);

// V2 binds the complete advertised Bazaar schema and chosen accepts option.
// Strict canonical JSON refuses silent dropping of undefined/non-JSON values.
const MAX_CONTRACT_BYTES = 65536;
function canonicalContract(value) {
  // Enforce the byte cap as each token is emitted, not after recursively
  // constructing an untrusted metadata string that could consume huge memory.
  let nodes=0, bytes=0;
  const parts=[];
  const emit=part=>{
    bytes+=Buffer.byteLength(part,'utf8');
    if(bytes>MAX_CONTRACT_BYTES) throw new RangeError('Bazaar contract exceeds 64 KiB');
    parts.push(part);
  };
  const write=(v,depth)=>{
    if(++nodes>10000 || depth>32) throw new TypeError('Bazaar contract too complex');
    if(v===null || typeof v==='boolean'){emit(JSON.stringify(v));return;}
    if(typeof v==='string'){
      if(Buffer.byteLength(v,'utf8')>MAX_CONTRACT_BYTES) throw new TypeError('Bazaar contract string too long');
      emit(JSON.stringify(v));return;
    }
    if(typeof v==='number' && Number.isFinite(v)){emit(JSON.stringify(v));return;}
    if(Array.isArray(v)){
      emit('[');
      for(let i=0;i<v.length;i++){if(i)emit(',');write(v[i],depth+1);}
      emit(']');return;
    }
    if(plain(v) && [Object.prototype,null].includes(Object.getPrototypeOf(v))){
      emit('{');
      const keys=Object.keys(v).sort();
      for(let i=0;i<keys.length;i++){
        if(i)emit(',');
        emit(JSON.stringify(keys[i])+':');
        write(v[keys[i]],depth+1);
      }
      emit('}');return;
    }
    throw new TypeError('Bazaar proof contract must contain JSON values only');
  };
  write(value,0);
  return parts.join('');
}
function hashAdvertisedContract(entry, selectedAcceptTerms) {
  const serialized=canonicalContract({bazaar:entry.extensions.bazaar,selectedAcceptTerms});
  if (Buffer.byteLength(serialized,'utf8') > MAX_CONTRACT_BYTES) throw new RangeError('Bazaar contract exceeds 64 KiB');
  return createHash('sha256').update('stellar-bazaar-advertised-contract/v2\0','utf8')
    .update(serialized,'utf8').digest('hex');
}

function nonEmpty(v, field) {
  if (typeof v !== 'string' || !v.trim() || v.length > 2048) throw new TypeError(`Invalid ${field}`);
  return v;
}
function checkedUrl(raw) {
  const s = nonEmpty(raw, 'resource.url');
  let u;
  try {u = new URL(s);} catch {throw new TypeError('Invalid resource.url URL');}
  if (u.protocol !== 'https:' || u.username || u.password || u.hash || !u.hostname || u.port) {
    throw new TypeError('resource.url must be public-style HTTPS without credentials, fragment or nonstandard port');
  }
  // Refuse an URL-equivalent signed spelling mismatch (normalization risks).
  if (u.href !== s) throw new TypeError('resource.url must be canonical absolute HTTPS');
  return u;
}
function quoteOf(entry, selectedAccept = 0) {
  if (!plain(entry) || entry.x402Version !== 2 || !Array.isArray(entry.accepts)) {
    throw new TypeError('Expected original x402 v2 PaymentRequired/Bazaar listing');
  }
  const resourceUrl = typeof entry.resource === 'string' ? entry.resource : entry.resource?.url;
  const url = checkedUrl(resourceUrl);
  const input = entry.extensions?.bazaar?.info?.input;
  if (!plain(input)) throw new TypeError('Missing Bazaar info.input');
  let identity;
  if (input.type === 'http' && METHODS.has(input.method)) {
    identity = {type:'http', method:input.method, toolName:null};
  } else if (input.type === 'mcp' && typeof input.toolName === 'string' && input.toolName.trim() && plain(input.inputSchema)) {
    identity = {type:'mcp', method:null, toolName:input.toolName};
  } else throw new TypeError('Invalid Bazaar HTTP/MCP identity');
  if (!Number.isSafeInteger(selectedAccept) || selectedAccept < 0 || selectedAccept >= entry.accepts.length) {
    throw new RangeError('Invalid accepts selection');
  }
  const a = entry.accepts[selectedAccept];
  if (!plain(a) || !ACCEPTS_RE.test(a.amount ?? '') || a.amount.length > 100) {
    throw new TypeError('Missing atomic-string accepts.amount');
  }
  const quote = {
    scheme:nonEmpty(a.scheme,'accepts.scheme'),
    network:nonEmpty(a.network,'accepts.network'),
    asset:nonEmpty(a.asset,'accepts.asset'),
    amount:a.amount,
    payTo:nonEmpty(a.payTo,'accepts.payTo')
  };
  identity.contractSha256=hashAdvertisedContract(entry,a);
  return {origin:url.origin,resourceUrl:url.href,identity,selectedAccept,quote};
}

export function createChallenge() {return randomBytes(32).toString('base64url');}
function validateChallenge(nonce) {
  if (typeof nonce !== 'string' || !CHALLENGE_RE.test(nonce)) throw new TypeError('Expected 32-byte base64url verifier nonce');
  if (Buffer.from(nonce,'base64url').length !== 32) throw new TypeError('Malformed nonce');
}
function checkedTimes(issuedAt,expiresAt,now) {
  if (![issuedAt,expiresAt,now].every(Number.isSafeInteger) || expiresAt <= issuedAt ||
      expiresAt - issuedAt > MAX_LIFETIME_MS || issuedAt > now + CLOCK_SKEW_MS ||
      expiresAt <= now - CLOCK_SKEW_MS) throw new RangeError('Proof expired, issued in future, or lifetime too long');
}
export function statementFor(entry,{nonce,issuedAt,expiresAt,selectedAccept=0}={}) {
  validateChallenge(nonce);
  if (!Number.isSafeInteger(issuedAt) || !Number.isSafeInteger(expiresAt)) throw new TypeError('Expected integer millisecond timestamps');
  const {origin,resourceUrl,identity,quote} = quoteOf(entry,selectedAccept);
  // Ordered, fixed-shape JSON is the signature preimage. Never sign arbitrary incoming objects.
  return {domain:PROOF_DOMAIN,origin,resourceUrl,identity,selectedAccept,quote,nonce,issuedAt,expiresAt};
}
function keyToB64(publicKey) {
  const k = publicKey?.type === 'public' ? publicKey : createPublicKey(publicKey);
  if (k.asymmetricKeyType !== 'ed25519') throw new TypeError('Ed25519 key required');
  return k.export({format:'der',type:'spki'}).toString('base64url');
}
function keyFromB64(raw) {
  if (typeof raw !== 'string' || raw.length > 256 || !/^[A-Za-z0-9_-]+$/.test(raw)) throw new TypeError('Invalid SPKI encoding');
  const key = createPublicKey({key:Buffer.from(raw,'base64url'),format:'der',type:'spki'});
  if (key.asymmetricKeyType !== 'ed25519') throw new TypeError('Ed25519 public key required');
  if (keyToB64(key) !== raw) throw new TypeError('Noncanonical key encoding');
  return key;
}
export function signProof(entry,{nonce,privateKeyPem,selectedAccept=0,now=Date.now(),lifetimeMs=30_000}={}) {
  if (!Number.isSafeInteger(now) || !Number.isSafeInteger(lifetimeMs) || lifetimeMs < 1000 || lifetimeMs > MAX_LIFETIME_MS) {
    throw new RangeError('Invalid proof issuance time or lifetime');
  }
  const privateKey=privateKeyPem?.type === 'private' ? privateKeyPem : createPrivateKey(privateKeyPem);
  if (privateKey.asymmetricKeyType !== 'ed25519') throw new TypeError('Ed25519 private key required');
  const statement=statementFor(entry,{nonce,selectedAccept,issuedAt:now,expiresAt:now+lifetimeMs});
  const publicKey=keyToB64(privateKey);
  const signature=sign(null,Buffer.from(JSON.stringify(statement),'utf8'),privateKey).toString('base64url');
  return {statement,publicKey,signature};
}

/** Verify against an OUT-OF-BAND PINNED key. Do not pass proof.publicKey as the pin. */
export function verifyPinnedProof(entry,proof,{nonce,pinnedPublicKey,now=Date.now(),selectedAccept=0}={}) {
  if (!plain(proof) || !plain(proof.statement) || typeof proof.signature !== 'string' || !pinnedPublicKey) {
    throw new TypeError('Proof, signature and independent key pin required');
  }
  validateChallenge(nonce);
  checkedTimes(proof.statement.issuedAt,proof.statement.expiresAt,now);
  const expected = statementFor(entry,{nonce,selectedAccept,issuedAt:proof.statement.issuedAt,expiresAt:proof.statement.expiresAt});
  const canonical = JSON.stringify(expected);
  // Strict exact-shape equality detects silent ignored/additional/unbound fields.
  if (JSON.stringify(proof.statement) !== canonical) throw new Error('Proof statement differs from original resource and quote');
  const key = keyFromB64(proof.publicKey);
  if (keyToB64(pinnedPublicKey) !== proof.publicKey) throw new Error('Seller signing key differs from independent pin');
  const raw=Buffer.from(proof.signature,'base64url');
  if (raw.length !== 64 || raw.toString('base64url') !== proof.signature ||
      !verify(null,Buffer.from(canonical,'utf8'),key,raw)) throw new Error('Invalid seller proof signature');
  return {verified:true,trust:'pinned-ed25519-key',origin:expected.origin,resourceUrl:expected.resourceUrl,
    identity:expected.identity,quote:expected.quote,expiresAt:expected.expiresAt};
}

// Public-address-only DNS pin; HTTPS request uses the vetted answer for this connection.
const rejected = new BlockList();
for (const [ip,prefix] of [
  ['0.0.0.0',8],['10.0.0.0',8],['100.64.0.0',10],['127.0.0.0',8],['169.254.0.0',16],
  ['172.16.0.0',12],['192.0.0.0',24],['192.0.2.0',24],['192.168.0.0',16],
  ['198.18.0.0',15],['198.51.100.0',24],['203.0.113.0',24],['224.0.0.0',4],['240.0.0.0',4]
]) rejected.addSubnet(ip,prefix,'ipv4');
for (const [ip,prefix] of [
  ['::',128],['::1',128],['fc00::',7],['fe80::',10],['ff00::',8],
  ['2001:db8::',32],['::ffff:0:0',96]
]) rejected.addSubnet(ip,prefix,'ipv6');
function safeDnsHost(host) {
  const h=host.toLowerCase().replace(/\.$/,'');
  if (isIP(h) || h==='localhost' || h.endsWith('.localhost') || h.endsWith('.local') ||
      h.endsWith('.internal') || h.endsWith('.test') || h.endsWith('.invalid') || h.endsWith('.example') ||
      !h.includes('.')) throw new TypeError('Seller origin must have a public DNS hostname');
}
async function publicAddress(host) {
  safeDnsHost(host);
  const addresses=await lookup(host,{all:true,verbatim:true});
  if (!addresses.length) throw new Error('No seller DNS answers');
  // Reject mixed public/private answer sets, not just the first chosen address.
  for (const a of addresses) if (![4,6].includes(a.family) || rejected.check(a.address,`ipv${a.family}`)) {
    throw new Error('Seller DNS resolved to a non-public address');
  }
  return addresses[0];
}

/**
 * Retrieve per-challenge proof from the seller's ACTUAL HTTPS origin.
 * Only this origin HTTPS/TLS observation can establish DNS-domain control.
 * It does NOT establish Stellar account control, merchant legality or settlement.
 */
export async function fetchOriginProof(entry,{nonce,timeoutMs=5000}={}) {
  validateChallenge(nonce);
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 15000) throw new RangeError('Invalid timeout');
  const {origin}=quoteOf(entry);
  const url=new URL(origin);
  // One absolute deadline covers DNS, TLS handshake and the full response body.
  // Socket idle timeouts alone can be defeated by a trickling response; and DNS
  // resolution can hang before a request-level timeout would even be installed.
  const deadline=AbortSignal.timeout(timeoutMs);
  const timedOut=new Promise((_,reject)=>{
    deadline.addEventListener('abort',()=>reject(new Error('Seller proof exceeded DNS/TLS/response deadline')), {once:true});
  });
  const pinned=await Promise.race([publicAddress(url.hostname),timedOut]);
  const path=`${WELL_KNOWN}?nonce=${encodeURIComponent(nonce)}`;
  return await new Promise((resolve,reject)=>{
    const req=https.request({protocol:'https:',hostname:url.hostname,port:443,path,method:'GET',
      signal:deadline,
      headers:{accept:'application/json','user-agent':'StellarBazaarSellerProof/1'},
      lookup:(_hostname,_options,cb)=>cb(null,pinned.address,pinned.family)},res=>{
      if (res.statusCode!==200) {res.resume();reject(new Error(`Seller origin returned HTTP ${res.statusCode}`));return;}
      const type=String(res.headers['content-type']||'').toLowerCase();
      if (!/^application\/json(?:\s*;|$)/.test(type)) {res.resume();reject(new Error('Seller proof must be JSON'));return;}
      const chunks=[];let count=0;
      res.on('data',chunk=>{count+=chunk.length;if(count>65536){res.destroy(new RangeError('Seller proof exceeds 64 KiB'));return;}chunks.push(chunk);});
      res.on('end',()=>{try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));}catch(e){reject(e);}});
      res.on('error',reject);
    });
    // The AbortSignal owns the hard wall clock timeout for this request.
    req.on('error',reject);req.end();
  });
}
/** Verification of fresh signed data fetched from exact seller HTTPS origin. */
export async function verifyOriginProof(entry,{nonce,now=Date.now(),selectedAccept=0,timeoutMs=5000}={}) {
  const proof=await fetchOriginProof(entry,{nonce,timeoutMs});
  // Here the seller key is pinned to the HTTPS origin observation itself.
  const pinnedPublicKey=keyFromB64(proof?.publicKey);
  const result=verifyPinnedProof(entry,proof,{nonce,pinnedPublicKey,now,selectedAccept});
  return {...result,trust:'seller-https-origin-and-ed25519',publicKey:proof.publicKey};
}

/**
 * MIT — SCF SF52: source-contract adapter for SF31 buyer + SF43 Stellar testnet verifier.
 * Pure interpretation: no wallet, signer, provider request, paid retry or funds transfer.
 */
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

export const VERSION = 'scf52.buyer-outcome.v1';
const STATES = new Set(['NO_PAYMENT_REQUIRED', 'UNPAID_HTTP_ERROR', 'DELIVERED_REPORTED_SETTLED',
  'SETTLEMENT_PENDING', 'PAYMENT_REPORTED_FAILED', 'PAYMENT_OUTCOME_UNKNOWN',
  'BLOCKED_BEFORE_SIGNATURE']);
const MAX_I128 = 170141183460469231731687303715884105727n;
const hash = v => typeof v === 'string' && /^[0-9a-f]{64}$/.test(v);
const obj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const tag = v => typeof v === 'string' && /^[\w.:-]{1,128}$/.test(v);
// Positive Soroban i128 atomics fit in at most 39 decimal digits.
// Bound untrusted observations before regex and BigInt work.
const amount = v => typeof v === 'string' && v.length <= 39 &&
  /^[1-9][0-9]*$/.test(v) && BigInt(v) <= MAX_I128;
function requireOk(ok, code) { if (!ok) throw new TypeError(code); }
function date(v) {
  const d = typeof v === 'string' ? new Date(v) : null;
  requireOk(d && !Number.isNaN(d.valueOf()) && d.toISOString() === v, 'OBSERVATION_TIME_INVALID');
  return v;
}
function terms(v) {
  requireOk(obj(v) && v.scheme === 'exact' &&
    ['stellar:testnet', 'stellar:pubnet'].includes(v.network) &&
    typeof v.asset === 'string' && v.asset.length > 0 && v.asset.length <= 128 &&
    typeof v.payTo === 'string' && v.payTo.length > 0 && v.payTo.length <= 128 &&
    amount(v.amount), 'BUYER_PAYMENT_TERMS_INVALID');
  return { scheme:v.scheme, network:v.network, asset:v.asset,
    payTo:v.payTo, amount:v.amount };
}

/** Transform a real SF31 result object to a serializable, non-secret observation.
 * Never serialize `Response`, signed headers, challenge, signer, body, or error cause.
 */
export function captureBuyerResult(buyer, { observedAt = new Date().toISOString() } = {}) {
  requireOk(obj(buyer) && STATES.has(buyer.status) && tag(buyer.intentId), 'BUYER_RESULT_INVALID');
  const accepted = buyer.requirement ? terms(buyer.requirement) : null;
  requireOk(Number.isSafeInteger(buyer.attempts) && buyer.attempts >= 1 && buyer.attempts <= 2,
    'BUYER_ATTEMPTS_INVALID');
  requireOk(Number.isSafeInteger(buyer.httpStatus) && buyer.httpStatus >= 100 && buyer.httpStatus <= 599,
    'BUYER_HTTP_STATUS_INVALID');
  if (buyer.status === 'NO_PAYMENT_REQUIRED' || buyer.status === 'UNPAID_HTTP_ERROR') {
    // SF31 distinguishes a free successful HTTP response from an unsuccessful
    // unsigned first request. Neither may invent signed attempts or receipts.
    const free = buyer.status === 'NO_PAYMENT_REQUIRED';
    requireOk(accepted === null && buyer.settlement === 'NOT_REQUESTED' &&
      buyer.attempts === 1 && buyer.receipt == null &&
      (free ? buyer.httpStatus >= 200 && buyer.httpStatus < 300 :
        buyer.httpStatus !== 402 && (buyer.httpStatus < 200 || buyer.httpStatus >= 300)),
      free ? 'FREE_RESULT_INCONSISTENT' : 'UNPAID_HTTP_RESULT_INCONSISTENT');
  } else {
    requireOk(accepted !== null && buyer.attempts === 2, 'PAID_RESULT_MISSING_SIGNED_ATTEMPT');
  }
  const receipt = buyer.receipt && obj(buyer.receipt) ? {
    success: buyer.receipt.success === true,
    network: ['stellar:testnet', 'stellar:pubnet'].includes(buyer.receipt.network) ? buyer.receipt.network : null,
    transaction: hash(buyer.receipt.transaction) ? buyer.receipt.transaction : null,
  } : null;
  return Object.freeze({ intentId:buyer.intentId, observedAt:date(observedAt),
    buyer:{ status:buyer.status, attempts:buyer.attempts, httpStatus:buyer.httpStatus,
      settlement:buyer.settlement??null, requirement:accepted, receipt,
      reason: typeof buyer.reason === 'string' ? buyer.reason.slice(0,128) : null }});
}

/** SF31 BuyerError may be thrown after the signed request was sent. Preserve that
 * distinction without copying the error's potentially sensitive cause/stack.
 */
export function captureBuyerError({ intentId, error, observedAt = new Date().toISOString() }) {
  requireOk(tag(intentId) && obj(error) && typeof error.paymentSent === 'boolean', 'BUYER_ERROR_INVALID');
  return Object.freeze({ intentId, observedAt:date(observedAt), buyer:{
    status:error.paymentSent ? 'PAYMENT_OUTCOME_UNKNOWN' : 'BLOCKED_BEFORE_SIGNATURE',
    attempts:error.paymentSent ? 2 : 0, httpStatus:null, settlement:'UNKNOWN',
    requirement:null, receipt:null, reason:tag(error.code) ? error.code : 'BUYER_ERROR' }});
}

/** Interpret normalized outcomes. A positive seller HTTP/receipt is NOT an on-chain
 * transfer; SF43 observes an exact transfer on the approved Stellar network.
 */
export function analyzeOne(record) {
  requireOk(obj(record) && tag(record.intentId) && date(record.observedAt), 'RECORD_INVALID');
  const b=record.buyer;
  requireOk(obj(b) && STATES.has(b.status), 'BUYER_STATE_INVALID');
  const t=b.requirement === null || b.requirement === undefined ? null : terms(b.requirement);
  const paid=b.attempts===2;
  requireOk(Number.isInteger(b.attempts) && b.attempts>=0 && b.attempts<=2, 'BAD_ATTEMPT_COUNT');
  const reported=b.status==='DELIVERED_REPORTED_SETTLED';
  const c=record.chain??null;
  const d=record.delivery??null;
  let state, evidence='NONE', ledger=null;
  if (b.status==='BLOCKED_BEFORE_SIGNATURE' || b.status==='NO_PAYMENT_REQUIRED' ||
      b.status==='UNPAID_HTTP_ERROR') {
    requireOk(!c && !d && !t && !paid, 'NONPAYMENT_HAS_PAID_EVIDENCE');
    state=b.status;
  } else if (!t) {
    requireOk(b.status==='PAYMENT_OUTCOME_UNKNOWN' && !c && !d, 'UNKNOWN_TERMS_WITH_PROOF');
    state='SIGNED_RESULT_UNCERTAIN';
  } else if (!paid) {
    throw new TypeError('SIGNED_ATTEMPT_REQUIRED');
  } else {
    const receipt=b.receipt;
    const receiptValid=obj(receipt) && receipt.success===true &&
      receipt.network===t.network && hash(receipt.transaction);
    const chainPositive=obj(c) && ['TOKEN_TRANSFER_MATCHED_TESTNET','TOKEN_TRANSFER_MATCHED_PUBNET'].includes(c.status);
    const expectedStatus=t.network==='stellar:testnet'?'TOKEN_TRANSFER_MATCHED_TESTNET':'TOKEN_TRANSFER_MATCHED_PUBNET';
    const consistent=chainPositive && c.status===expectedStatus && receiptValid &&
      c.proof==='RPC_TX_AND_SEP41_TRANSFER_EVENT_MATCH' &&
      c.network===t.network && c.transaction===receipt.transaction &&
      c.contractId===t.asset && c.recipient===t.payTo &&
      c.amountAtomic===t.amount && Number.isSafeInteger(c.ledger) && c.ledger>0;
    if (chainPositive && !consistent) state='PROOF_CONFLICT';
    else if (consistent) {
      evidence=t.network==='stellar:testnet'?'MATCHED_SF43_TESTNET_TRANSFER':'MATCHED_SF43_PUBNET_TRANSFER';
      ledger=c.ledger;
      const delivered=reported && obj(d) && d.status==='HTTP_BODY_OBSERVED' &&
        Number.isInteger(d.httpStatus) && d.httpStatus>=200 && d.httpStatus<300 &&
        hash(d.bodySha256);
      state=delivered?'TRANSFER_AND_HTTP_BODY_OBSERVED':'TRANSFER_VERIFIED_DELIVERY_UNCONFIRMED';
    } else if (c && !obj(c)) state='PROOF_CONFLICT';
    else if (reported && !receiptValid) state='SELLER_RECEIPT_CONFLICT';
    else if (reported) state='SELLER_REPORTED_ONLY';
    else if (b.status==='SETTLEMENT_PENDING') state='PENDING_RECONCILIATION';
    else if (b.status==='PAYMENT_REPORTED_FAILED') state='SELLER_REPORTED_FAILED';
    else state='SIGNED_RESULT_UNCERTAIN';
  }
  return Object.freeze({ intentId:record.intentId, observedAt:record.observedAt,
    status:state, network:t?.network??null, asset:t?.asset??null,
    amountAtomic:t?.amount??null, signedAttempt:paid, sellerReportedSuccess:reported,
    independentlyVerifiedTransfer:['MATCHED_SF43_TESTNET_TRANSFER','MATCHED_SF43_PUBNET_TRANSFER'].includes(evidence),
    observedHttpBody:state==='TRANSFER_AND_HTTP_BODY_OBSERVED',
    chainEvidence:evidence, ledger });
}

/** Aggregate one terminal snapshot per intent: no duplicate revenue/event inflation.
 * Atomic units are grouped per network+asset, never mislabelled as USD or cash.
 */
export function aggregateOutcomes(records) {
  requireOk(Array.isArray(records) && records.length<=100_000, 'RECORDS_INVALID_OR_TOO_MANY');
  // A distinct intentId is not evidence of a distinct on-chain transfer. SF43
  // reports a matched event but does not expose an event index, so identical
  // transfer tuples must not be credited twice from a reused receipt.
  const seen=new Set(), seenChainProofs=new Set(), outcomes=[], byAsset=new Map();
  const counts={ total:0,unpaidHttpFailures:0,signedAttempts:0,sellerReportedSuccess:0,verifiedTransfers:0,
    transferAndBodyObserved:0,proofConflicts:0,uncertainOrPending:0 };
  for(const record of records) {
    const result=analyzeOne(record);
    requireOk(!seen.has(result.intentId), 'DUPLICATE_INTENT_ID');seen.add(result.intentId);
    outcomes.push(result);counts.total++;
    if(result.status==='UNPAID_HTTP_ERROR')counts.unpaidHttpFailures++;
    if(result.signedAttempt)counts.signedAttempts++;
    if(result.sellerReportedSuccess)counts.sellerReportedSuccess++;
    if(result.status==='PROOF_CONFLICT'||result.status==='SELLER_RECEIPT_CONFLICT') counts.proofConflicts++;
    if(['SIGNED_RESULT_UNCERTAIN','PENDING_RECONCILIATION','SELLER_REPORTED_ONLY',
      'TRANSFER_VERIFIED_DELIVERY_UNCONFIRMED'].includes(result.status))counts.uncertainOrPending++;
    if(result.independentlyVerifiedTransfer) {
      const c=record.chain;
      const proofKey=JSON.stringify([result.network,c.transaction,result.asset,
        record.buyer.requirement.payTo,result.amountAtomic]);
      requireOk(!seenChainProofs.has(proofKey), 'DUPLICATE_CHAIN_TRANSFER_PROOF');
      seenChainProofs.add(proofKey);
      counts.verifiedTransfers++;
      const key=JSON.stringify([result.network,result.asset]);
      byAsset.set(key,(byAsset.get(key)||0n)+BigInt(result.amountAtomic));
    }
    if(result.observedHttpBody)counts.transferAndBodyObserved++;
  }
  return { schema:VERSION, generatedAt:new Date().toISOString(), counts,
    observedTransferAtomicByAsset:[...byAsset].sort(([a],[b])=>a.localeCompare(b)).map(([key,total])=>{
      const [network,asset]=JSON.parse(key);return {network,asset,atomicTotal:total.toString()};
    }), outcomes,
    interpretation:'Observed transfer amounts are testnet atomic units, NOT USD, booked revenue, customer satisfaction or an SCF funding result. HTTP body presence does not prove useful fulfillment.' };
}

export async function cli(args=process.argv.slice(2)) {
  requireOk(args.length===2 && args[0]==='--input','USAGE: node outcomes.mjs --input observations.json');
  const fs=await import('node:fs/promises');
  const stats=await fs.stat(args[1]);requireOk(stats.size<=8*1024*1024,'INPUT_TOO_LARGE');
  const records=JSON.parse(await readFile(args[1],'utf8'));
  process.stdout.write(JSON.stringify(aggregateOutcomes(records),null,2)+'\n');
}
if (process.argv[1] && import.meta.url===pathToFileURL(process.argv[1]).href)
  cli().catch(e=>{console.error('SF52:',e.message);process.exitCode=2;});

// MIT. Read-only x402 Bazaar seller discoverability diagnostic. No wallet, payment or account calls.
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const MAX_JSON_BYTES = 2_000_000;
const MAX_HEADER_BYTES = 64_000;
const URL_LIMIT = 2048;
const HTTP_METHODS = new Set(['GET','HEAD','POST','PUT','PATCH','DELETE']);

export function requireEndpoint(value, {allowLoopback = false} = {}) {
  if (typeof value !== 'string' || value.length > URL_LIMIT) throw new TypeError('Invalid endpoint URL');
  const url = new URL(value);
  if (url.username || url.password || url.hash) throw new TypeError('Credentials and URL fragments are not allowed');
  const loopback = ['127.0.0.1', '[::1]'].includes(url.hostname);
  if (url.protocol !== 'https:' && !(allowLoopback && loopback && url.protocol === 'http:')) {
    throw new TypeError('HTTPS required (local loopback needs --allow-loopback)');
  }
  if (!loopback && /^(localhost|.*\.localhost)$/i.test(url.hostname)) throw new TypeError('Local host not allowed');
  return url;
}

export function resourceKey(value) {
  try {
    // Original BazaarCatalog serializes resource as {url, ...metadata};
    // some external providers return a flat URL string. Accept either
    // without ever coercing an untrusted object into a URL candidate.
    const locator = typeof value === 'string' ? value :
      value !== null && typeof value === 'object' && !Array.isArray(value) &&
      typeof value.url === 'string' ? value.url : null;
    if (locator === null) return null;
    const url = new URL(locator);
    if (!['https:', 'http:'].includes(url.protocol)) return null;
    url.hash = '';
    if (url.pathname.length > 1) url.pathname = url.pathname.replace(/\/+$/, '');
    return url.toString();
  } catch { return null; }
}

export function decodeJsonHeader(value, label = 'header') {
  if (typeof value !== 'string' || value.length > MAX_HEADER_BYTES || !/^[A-Za-z0-9+/_=-]+$/.test(value)) {
    throw new TypeError(`Invalid ${label} encoding`);
  }
  const clean = value.trim().replace(/-/g, '+').replace(/_/g, '/');
  const buffer = Buffer.from(clean, 'base64');
  if (!buffer.length || buffer.length > MAX_HEADER_BYTES ||
      buffer.toString('base64').replace(/=+$/, '') !== clean.replace(/=+$/, '')) {
    throw new TypeError(`Invalid ${label} base64`);
  }
  const decoded = JSON.parse(buffer.toString('utf8'));
  if (!decoded || typeof decoded !== 'object' || Array.isArray(decoded)) throw new TypeError(`Invalid ${label} JSON`);
  return decoded;
}

export function bazaarExtensionOutcome(headerValue) {
  if (!headerValue) return {state: 'NOT_PROVIDED'};
  try {
    const object = decodeJsonHeader(headerValue, 'EXTENSION-RESPONSES');
    const entry = object.bazaar;
    if (!entry || !['success', 'processing', 'rejected'].includes(entry.status)) {
      return {state: 'NO_VALID_BAZAAR_STATUS'};
    }
    return {state: entry.status.toUpperCase(), ...(entry.status === 'rejected' && typeof entry.rejectedReason === 'string'
      ? {reason: entry.rejectedReason.slice(0, 300)} : {})};
  } catch (error) { return {state: 'INVALID_HEADER', error: String(error.message)}; }
}

export function inspectChallenge(status, header) {
  if (status !== 402) return {httpStatus: status, state: status === 200 ? 'UNPAID_GET_HTTP_200' : 'NOT_HTTP_402'};
  if (!header) return {httpStatus: status, state: 'NO_PAYMENT_REQUIRED_HEADER'};
  try {
    const payment = decodeJsonHeader(header, 'PAYMENT-REQUIRED');
    const accepts = Array.isArray(payment.accepts) ? payment.accepts : [];
    const routes = accepts.filter(x => x && typeof x === 'object').slice(0, 40).map(x => ({
      network: typeof x.network === 'string' ? x.network : null,
      scheme: typeof x.scheme === 'string' ? x.scheme : null,
      asset: typeof x.asset === 'string' ? x.asset : null,
      payTo: typeof x.payTo === 'string' ? x.payTo : null,
      amount: typeof x.amount === 'string' ? x.amount : null
    }));
    return {httpStatus: status, state: routes.length ? 'X402_402' : 'INVALID_ACCEPTS',
      x402Version: payment.x402Version ?? null,
      bazaarExtension: Boolean(payment.extensions?.bazaar),
      acceptsCount: accepts.length, accepts: routes};
  } catch (error) {
    return {httpStatus: status, state: 'INVALID_PAYMENT_REQUIRED', error: String(error.message)};
  }
}

// Diagnostic classification only: never attempts payment, settlement, indexing or a paid retry.
export function sellerDiscoveryReadiness(challenge) {
  if (challenge.state === 'CATALOG_NON_GET_ONLY') return {
    state: 'CATALOG_NON_GET_ONLY',
    diagnosis: 'This catalog entry declares only non-GET HTTP operations or MCP tools. No seller-origin GET was made; this is not a failed unpaid payment challenge.',
    nextAction: 'Use the documented method/tool and obtain seller permission before any real payment or invocation. Catalog visibility does not establish live origin readiness.'
  };
  if (challenge.state === 'UNPAID_GET_HTTP_200') return {
    state: 'UNPAID_200_NO_402_DECLARATION',
    diagnosis: 'An unauthenticated GET returned HTTP 200, not a 402 payment declaration. A Bazaar crawler using the same route cannot observe the paid offer from that response.',
    nextAction: 'Check default free-tier, cache, and health-shortcut paths. If discovery requires a paid offer, expose a 402 with Bazaar metadata on the unauthenticated path and make free access explicitly opt-in.'
  };
  if (challenge.state === 'X402_402' && challenge.bazaarExtension) return {
    state: 'UNPAID_402_BAZAAR_VISIBLE',
    diagnosis: 'An unauthenticated 402 with Bazaar metadata is visible. Catalog indexing and any actual settlement remain separate checks.'
  };
  if (challenge.state === 'X402_402') return {
    state: 'UNPAID_402_WITHOUT_BAZAAR',
    diagnosis: 'The HTTP 402 lists payment terms but no Bazaar declaration; a discovery crawler may not have the resource metadata it needs.'
  };
  return {
    state: 'NO_VALID_UNPAID_BAZAAR_402',
    diagnosis: 'A valid unauthenticated HTTP 402 with Bazaar metadata was not observed; inspect the seller response and any fetch or decoding error.'
  };
}

async function getBody(response) {
  const reader = response.body?.getReader();
  if (!reader) return '';
  const pieces = [];
  let total = 0;
  try {
    for (;;) {
      const {value, done} = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > MAX_JSON_BYTES) throw new RangeError('HTTP response exceeds read-only byte limit');
      pieces.push(value);
    }
  } finally { reader.releaseLock(); }
  return Buffer.concat(pieces, total).toString('utf8');
}

async function readEndpoint(fetchImpl, url, {json = false} = {}) {
  const response = await fetchImpl(url, {
    method: 'GET', redirect: 'error', headers: {accept: 'application/json'},
    signal: AbortSignal.timeout(15_000)
  });
  const header = response.headers;
  const body = json && response.ok ? JSON.parse(await getBody(response)) : null;
  return {status: response.status, header, body};
}

function listItems(page) {
  if (Array.isArray(page?.items)) return page.items;
  if (Array.isArray(page?.resources)) return page.resources;
  throw new TypeError('Discovery body has no items/resources array');
}

function networkSummary(item) {
  return [...new Set((Array.isArray(item?.accepts) ? item.accepts : [])
    .map(x => x?.network).filter(x => typeof x === 'string'))];
}

export async function inspectCatalog({catalogUrl, targetResource, payTo, network, allowLoopback = false,
  pageLimit = 100, maxPages = 500, fetchImpl = fetch}) {
  const endpoint = requireEndpoint(catalogUrl, {allowLoopback});
  const target = resourceKey(targetResource);
  if (!target) throw new TypeError('Invalid target resource URL');
  if (!Number.isSafeInteger(pageLimit) || pageLimit < 1 || pageLimit > 200 ||
      !Number.isSafeInteger(maxPages) || maxPages < 1 || maxPages > 2000) {
    throw new TypeError('Invalid pagination options');
  }
  const matches = [], samePayToOtherResource = [];
  // Read the original operation contract across every matching record, not just displayed samples.
  const httpMethods = new Set();
  let mcpToolCount = 0, unresolvedMethodCount = 0;
  // Keep a bounded sample for display, but classify using ALL matching records.
  let matchingResourceCount = 0;
  const matchEvidence = {network: false, payTo: false, paired: false};
  const seenKeys = new Set(), seenPageSignatures = new Set(), seenCursors = new Set();
  let offset = 0, cursor = null, useCursor = false, knownTotal = null;
  let complete = false, pages = 0, rawRows = 0, reason = null;
  for (let i = 0; i < maxPages; i++) {
    const pageUrl = new URL(endpoint);
    pageUrl.searchParams.set('limit', String(pageLimit));
    if (useCursor) pageUrl.searchParams.set('cursor', cursor);
    else pageUrl.searchParams.set('offset', String(offset));
    let body;
    try {
      const result = await readEndpoint(fetchImpl, pageUrl, {json: true});
      if (result.status !== 200) throw new Error(`Discovery HTTP ${result.status}`);
      body = result.body;
    } catch (error) { reason = `Page ${i + 1}: ${String(error.message)}`; break; }
    let items;
    try { items = listItems(body); }
    catch (error) { reason = `Page ${i + 1}: ${String(error.message)}`; break; }
    pages++;
    rawRows += items.length;
    const pageKeys = [];
    for (const item of items) {
      const resource = resourceKey(item?.resource);
      const toolName = item?.extensions?.bazaar?.info?.input?.toolName ?? '';
      const uniqueKey = `${resource ?? '?'}\0${toolName}`;
      pageKeys.push(uniqueKey);
      seenKeys.add(uniqueKey);
      const accepts = Array.isArray(item?.accepts) ? item.accepts : [];
      const related = typeof payTo === 'string' && accepts.some(x =>
        typeof x?.payTo === 'string' && x.payTo.toLowerCase() === payTo.toLowerCase());
      const hasNetwork = network ? accepts.some(x => x?.network === network) : null;
      // It is not enough for network and recipient to occur on DIFFERENT
      // alternatives; the seller must actually accept their paired route.
      const hasPair = network && payTo ? accepts.some(x =>
        x?.network === network && typeof x?.payTo === 'string' &&
        x.payTo.toLowerCase() === payTo.toLowerCase()) : null;
      if (resource === target) {
        matchingResourceCount++;
        const input = item?.extensions?.bazaar?.info?.input;
        const kind = item?.type ?? input?.type;
        const method = typeof input?.method === 'string' ? input.method.toUpperCase() : null;
        if (kind === 'mcp' && input?.type === 'mcp') mcpToolCount++;
        else if (kind === 'http' && HTTP_METHODS.has(method)) httpMethods.add(method);
        else unresolvedMethodCount++;
        matchEvidence.network ||= Boolean(hasNetwork);
        matchEvidence.payTo ||= Boolean(related);
        matchEvidence.paired ||= Boolean(hasPair);
        if (matches.length < 50) matches.push({resource, type: item?.type ?? null,
          toolName: String(toolName), x402Version: item?.x402Version ?? null,
          networks: networkSummary(item), declaredMethod: kind === 'http' && HTTP_METHODS.has(method) ? method : null,
          declaredType: kind ?? null, desiredNetworkFound: hasNetwork,
          desiredPayToFound: payTo ? related : null, desiredPaymentRouteFound: hasPair});
      } else if (related && samePayToOtherResource.length < 15) {
        samePayToOtherResource.push({resource, networks: networkSummary(item)});
      }
    }
    const signature = pageKeys.join('\n');
    if (items.length && seenPageSignatures.has(signature)) {
      reason = `Repeated page contents at page ${pages}; provider may ignore pagination`; break;
    }
    seenPageSignatures.add(signature);
    const pagination = body?.pagination && typeof body.pagination === 'object' ? body.pagination : {};
    if (Number.isSafeInteger(pagination.total) && pagination.total >= 0) knownTotal = pagination.total;
    const nextCursor = pagination.nextCursor ?? pagination.next_cursor ?? pagination.cursor;
    // A filtered cursor page may legitimately be empty while another page has
    // rows. Follow its actual next cursor BEFORE claiming the catalog exhausted.
    // A repeated cursor (including A -> B -> A) cannot establish exhaustion.
    if (typeof nextCursor === 'string' && nextCursor.length > 0) {
      if (seenCursors.has(nextCursor) || (useCursor && nextCursor === cursor)) {
        reason = `Repeated cursor at page ${pages}; provider pagination made no progress`;
        break;
      }
      seenCursors.add(nextCursor);
      useCursor = true;
      cursor = nextCursor;
      continue;
    }
    if (knownTotal !== null && seenKeys.size > knownTotal) {
      reason = 'Provider declared total contradicts observed unique rows';
      break;
    }
    if (useCursor) {
      if (knownTotal !== null && seenKeys.size < knownTotal) reason = 'Cursor ended before declared total';
      else complete = true;
      break;
    }
    if (knownTotal !== null && seenKeys.size >= knownTotal) { complete = true; break; }
    if (!items.length) {
      if (knownTotal !== null && seenKeys.size < knownTotal) reason = 'Empty page before declared total';
      else complete = true;
      break;
    }
    // Offset-only providers without a total get an extra empty-page probe.
    offset += items.length;
  }
  if (!complete && !reason) reason = `Reached maxPages=${maxPages} before proving catalog exhaustiveness`;
  return {endpoint: endpoint.toString(), pages, rawRows, uniqueKeys: seenKeys.size,
    declaredTotal: knownTotal, complete, incompleteReason: reason,
    matchingResourceCount,
    operationEvidence: {httpMethods: [...httpMethods].sort(), mcpToolCount, unresolvedMethodCount},
    matchingEvidence: {
      desiredNetworkFound: network ? matchEvidence.network : null,
      desiredPayToFound: payTo ? matchEvidence.payTo : null,
      desiredPaymentRouteFound: network && payTo ? matchEvidence.paired : null
    },
    matches, matchingPayToOtherResources: samePayToOtherResource};
}

export async function diagnose({resourceUrl, catalogUrl, payTo, network, extensionResponses,
  allowLoopback = false, pageLimit = 100, maxPages = 500, fetchImpl = fetch}) {
  const resource = requireEndpoint(resourceUrl, {allowLoopback});
  const catalog = requireEndpoint(catalogUrl, {allowLoopback});
  async function probeUnpaidGet() {
    try {
      const result = await readEndpoint(fetchImpl, resource);
      return inspectChallenge(result.status, result.header.get('payment-required'));
    } catch (error) { return {state: 'FETCH_ERROR', error: String(error.message)}; }
  }
  const inspect = requestedPayTo => inspectCatalog({catalogUrl: catalog.toString(), targetResource: resource.toString(),
    payTo: requestedPayTo, network, allowLoopback, pageLimit, maxPages, fetchImpl});
  let challenge, summary;
  if (payTo) {
    // An explicit seller recipient permits one catalog pass before an origin probe.
    // Skip GET only when COMPLETE source records all declare non-GET or MCP operations.
    summary = await inspect(payTo);
    const methods = summary.operationEvidence;
    const skipGet = summary.complete && summary.matchingResourceCount > 0 &&
      methods.unresolvedMethodCount === 0 && !methods.httpMethods.includes('GET') &&
      (methods.httpMethods.length > 0 || methods.mcpToolCount > 0);
    challenge = skipGet ? {state: 'CATALOG_NON_GET_ONLY', observedVia: 'COMPLETE_CATALOG',
      declaredHttpMethods: methods.httpMethods, mcpToolCount: methods.mcpToolCount} : await probeUnpaidGet();
  } else {
    // Retain original single-offer payTo derivation when no recipient was given.
    // In that case the genuine origin response must precede the indexed catalog comparison.
    challenge = await probeUnpaidGet();
    const discoveredPayTo = challenge.acceptsCount === 1 ? challenge.accepts?.[0]?.payTo : null;
    summary = await inspect(discoveredPayTo);
  }
  const derivedPayTo = payTo || (challenge.acceptsCount === 1 ? challenge.accepts?.[0]?.payTo : null);
  const extension = bazaarExtensionOutcome(extensionResponses);
  let verdict = 'INCONCLUSIVE_CATALOG';
  if (summary.matchingResourceCount) {
    if (network && !summary.matchingEvidence.desiredNetworkFound)
      verdict = 'LISTED_WRONG_NETWORK';
    else if (derivedPayTo && !summary.matchingEvidence.desiredPayToFound)
      verdict = 'LISTED_WRONG_PAYTO';
    else if (network && derivedPayTo && !summary.matchingEvidence.desiredPaymentRouteFound)
      verdict = 'LISTED_PAYMENT_ROUTE_MISMATCH';
    else verdict = 'LISTED';
  } else if (summary.complete) verdict = 'NOT_LISTED_IN_EXHAUSTED_CATALOG';
  return {
    schema: 'stellar-forge.seller-visibility.v1', mode: 'READ_ONLY_UNAUTHENTICATED',
    seller: resource.toString(), network: network ?? null, desiredPayTo: derivedPayTo ?? null,
    challenge, sellerDiscovery: sellerDiscoveryReadiness(challenge), extensionResponse: extension, catalog: summary, verdict,
    interpretation: verdict === 'NOT_LISTED_IN_EXHAUSTED_CATALOG'
      ? (challenge.state === 'UNPAID_GET_HTTP_200'
        ? 'Not listed in this exhausted catalog, and the seller gave an unpaid HTTP 200 rather than a 402 declaration. Free-tier or cache shortcuts can prevent crawler discovery; verify the challenge path before attributing absence to the facilitator.'
        : 'Missing from this facilitator catalog at read time; successful payment alone does not prove catalog indexing.')
      : verdict === 'INCONCLUSIVE_CATALOG'
        ? 'Catalog coverage incomplete; do not interpret this as absence.'
        : verdict === 'LISTED_PAYMENT_ROUTE_MISMATCH'
          ? 'URL indexed, but no single accepted option combines the requested network and payTo.'
          : verdict === 'LISTED_WRONG_PAYTO'
            ? 'URL indexed, but its listed payment recipients do not match the seller recipient.'
            : 'Listing observed; check matching network, payment terms and seller origin separately.',
    excludes: ['No settlement or wallet verification', 'No facilitator indexing trigger', 'No payment made']
  };
}

function parseArgs(args) {
  const options = {};
  const values = new Set(['--resource','--catalog','--pay-to','--network','--extension-responses',
    '--extension-responses-file','--limit','--max-pages']);
  for (let i = 0; i < args.length; i++) {
    const flag = args[i];
    if (flag === '--allow-loopback') { options.allowLoopback = true; continue; }
    if (!values.has(flag) || !args[i+1] || args[i+1].startsWith('--')) throw new TypeError(`Invalid option: ${flag}`);
    const value = args[++i];
    const mapping = {'--resource':'resourceUrl','--catalog':'catalogUrl','--pay-to':'payTo',
      '--network':'network','--extension-responses':'extensionResponses',
      '--extension-responses-file':'extensionResponsesFile','--limit':'pageLimit','--max-pages':'maxPages'};
    options[mapping[flag]] = ['--limit','--max-pages'].includes(flag) ? Number(value) : value;
  }
  if (!options.resourceUrl || !options.catalogUrl) throw new TypeError('--resource and --catalog required');
  if (options.extensionResponses && options.extensionResponsesFile) throw new TypeError('Supply extension response in only one place');
  return options;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  (async () => {
    const options = parseArgs(process.argv.slice(2));
    if (options.extensionResponsesFile) {
      options.extensionResponses = (await readFile(options.extensionResponsesFile, 'utf8')).trim();
      delete options.extensionResponsesFile;
    }
    const result = await diagnose(options);
    process.stdout.write(JSON.stringify(result, null, 2) + '\n');
  })().catch(error => {
    process.stderr.write('SF52 diagnostic error: ' + String(error.message) + '\n');
    process.exitCode = 1;
  });
}

#!/usr/bin/env node
/** Local trusted-operator workflow over the original SF60 journal. No network. */
import { constants } from 'node:fs';
import { open, mkdir, rm, readFile } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { parseArgs } from 'node:util';
import { DurableCatalogTransaction, BATCH_SCHEMA, MAX_BATCH_BYTES, MAX_BATCH_OPERATIONS } from './journal.mjs';

const INPUT_SCHEMA = 'stellar-forge.catalog-batch-input/v1';
const AUTH_SCHEMA = 'stellar-forge.catalog-operator-authorities/v1';
const PLAN_SCHEMA = 'stellar-forge.catalog-import-plan/v1';
const fields = ['allowedOrigins','allowedRecipients','allowedNetworks','allowedSchemes'];
const plain = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const hash = v => createHash('sha256').update(v).digest('hex');
const fail = code => {throw new Error(code);};
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

async function load(path,limit) {
  if (typeof path !== 'string' || !path) fail('FILE_ARGUMENT_REQUIRED');
  const file = await open(resolve(path),constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const meta = await file.stat();
    if (!meta.isFile() || meta.size > limit) fail('INPUT_FILE_LIMIT');
    const parts=[]; let bytes=0;
    while (bytes <= limit) {
      const buffer=Buffer.alloc(Math.min(65536,limit+1-bytes));
      const {bytesRead}=await file.read(buffer,0,buffer.length,null);
      if (!bytesRead) break;
      bytes+=bytesRead; parts.push(buffer.subarray(0,bytesRead));
    }
    if (bytes > limit) fail('INPUT_FILE_LIMIT');
    const raw=Buffer.concat(parts);
    let document;
    try {document=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));}
    catch {fail('INPUT_JSON_INVALID');}
    return {document,sha256:hash(raw)};
  } finally {await file.close();}
}

/** Bind source rows to a SEPARATE authenticated operator authority file. */
export function bindOperations(input,authorities) {
  if (!plain(input) || input.schema !== INPUT_SCHEMA || !Array.isArray(input.operations) ||
      !input.operations.length || input.operations.length > MAX_BATCH_OPERATIONS) fail('INPUT_SCHEMA_INVALID');
  if (!plain(authorities) || authorities.schema !== AUTH_SCHEMA || !Array.isArray(authorities.sellers) ||
      !authorities.sellers.length || authorities.sellers.length > MAX_BATCH_OPERATIONS) fail('AUTHORITY_SCHEMA_INVALID');
  const bySeller=new Map();
  for (const raw of authorities.sellers) {
    if (!plain(raw) || typeof raw.sellerId !== 'string' || !/^[A-Za-z0-9_.:-]{1,128}$/.test(raw.sellerId) ||
        typeof raw.signer !== 'string' || raw.signer.length < 3 || raw.signer.length > 256 || bySeller.has(raw.sellerId)) fail('AUTHORITY_SELLER_INVALID');
    const authority={sellerId:raw.sellerId,signer:raw.signer};
    for (const key of fields) {
      if (!Array.isArray(raw[key]) || !raw[key].length || raw[key].length > 64 ||
          raw[key].some(x=>typeof x !== 'string' || !x || x.length > 256)) fail('AUTHORITY_POLICY_INVALID');
      authority[key]=new Set(raw[key]);
    }
    bySeller.set(raw.sellerId,authority);
  }
  return input.operations.map((row,index)=>{
    if (!plain(row) || !['upsert','retire'].includes(row.kind) || Object.hasOwn(row,'authority') ||
        Object.hasOwn(row,'signer')) fail(`INPUT_ROW_${index}_INVALID`);
    const sellerId=row.kind === 'upsert' ? row.candidate?.sellerId : row.sellerId;
    const authority=bySeller.get(sellerId);
    if (!authority) fail(`INPUT_ROW_${index}_AUTHORITY_MISSING`);
    return row.kind === 'upsert' ? {kind:'upsert',candidate:row.candidate,provenance:row.provenance,authority}
      : {kind:'retire',catalogKey:row.catalogKey,sellerId,sequence:row.sequence,
        provenance:row.provenance,reason:row.reason,signer:authority.signer};
  });
}

function terms(snapshot) {
  if (!snapshot) return '<span class="muted">Not in catalog</span>';
  return `<strong>${esc(snapshot.state)} · sequence ${snapshot.sequence}</strong><div>${esc(snapshot.resourceURL)}</div>`+
    snapshot.accepts.map(a=>`<div class="term">${esc(a.amount)} atomic · ${esc(a.asset)} · ${esc(a.network)}<br>${esc(a.scheme)} → ${esc(a.payTo)}</div>`).join('');
}
export function renderReview(plan, {notice = 'The operator must already have authenticated each seller and its source. This import does not verify signatures or settle payments. Atomic amounts below are advertised terms, not revenue.'} = {}) {
  const r=plan.review;
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">
<title>Catalog import review</title><style>
:root{font:15px/1.5 system-ui,sans-serif;color:#222;background:#f4f4f4}body{max-width:1200px;margin:32px auto;padding:0 20px}
h1{font-size:28px;margin-bottom:0}h2{font-size:17px;margin:0}header,section{background:#fff;border:1px solid #ccc;padding:20px;margin:16px 0}
.muted,small{color:#555}.stats{display:flex;gap:36px;flex-wrap:wrap}.stats b{font-size:24px;display:block}code{overflow-wrap:anywhere;font-size:12px}
article{border-top:1px solid #ddd;padding:18px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pair>div{min-width:0;overflow-wrap:anywhere}.pair small{display:block;margin-bottom:6px}
