      const options = {}, seen = new Set();
      for (let i = 0; i < args.length; i++) {
        const name = args[i];
        if (seen.has(name) || !['--directory', '--port', '--create-empty'].includes(name)) throw new Error(USAGE);
        seen.add(name);
