      content: input.content, provenance: { ...(input.provenance ?? {}),
        ...(input.kind === 'legacy-response' ? { kind: input.provenance?.kind ?? 'file', name: input.name,
          importedAt: new Date().toISOString(), importedBy: input.actor } : {}) } });
