function number(v,label,min=-Number.MAX_VALUE,max=Number.MAX_VALUE){if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max)fail('RESPONSE_CONTRACT',label+' is outside its documented numeric range',502);return v;}
